// Real paired workload: list_fill_vs_index_loop surface spelling
Pixel: struct {
    r: U8
    g: U8
    b: U8
    a: U8
}

run: fn() {
    row := [Pixel]{}
    loop i in 0..<65536 {
        row.push(Pixel{r: 0, g: 0, b: 0, a: 255})
    }
    total := 0
    loop frame in 0..<2048 {
        shade: U8.from_int(frame % 256) ?? 0
        value: Pixel{r: shade, g: shade, b: shade, a: 255}
        row.fill(0..<65536, value)
        total = total + Int.from_u8(row[frame].r)
    }
    loop pixel in row {
        total = total + Int.from_u8(pixel.r)
    }
    print("performance-surface:list_fill_vs_index_loop:{total}")
}

