// Real paired workload: net_read_into_vs_read surface spelling
package: {
    name: "read_into_pair_surface"
    authority: { allow: [IO, Mem.Alloc, Net, Time.Wait] }
}
use net: core.net

run: fn() {
    listener: net.tcp_listen("127.0.0.1:0") ?? panic("listen")
    address: net.listener_local_socket_addr(listener) ?? panic("listener address")
    writer: task {
        accepting := listener.move()
        side: accepting.accept() ?? panic("accept")
        block := [U8]{}
        loop _ in 0..<4096 { block.push(U8{97}) }
        loop _ in 0..<16384 { side.write_all(block) ?? panic("write") }
        side.close() ?? panic("close")
    }
    client := net.tcp_connect_addr(address) ?? panic("connect")
    total := 0
    reads := 0
    buffer := [U8]{}
    loop {
        buffer.clear()
        count: client.read_into(buffer, 4096) ?? panic("read_into")
        if count == 0 -> break
        total += count
        reads += 1
    }
    writer.join() ?? panic("writer")
    eprint("reads={reads}")
    print("performance-surface:net_read_into_vs_read:{total}")
}

