package: {
    name: "read_into_pair_plain"
    authority: { allow: [IO, Mem.Alloc, Net, Time.Wait] }
}
use net: core.net

run: fn() {
    listener: net.tcp_listen("127.0.0.1:0") ?? panic("listen")
    address: net.listener_local_socket_addr(listener) ?? panic("listener address")
    writer: task {
        accepting := listener.move()
